    private static List<LlamadaHerramienta> LlamadasDe(ChatResponse respuesta) =>
        [.. respuesta.Messages
            .SelectMany(mensaje => mensaje.Contents)
            .OfType<FunctionCallContent>()
            .Select(llamada => new LlamadaHerramienta(llamada.CallId, llamada.Name, JsonSerializer.Serialize(llamada.Arguments ?? new Dictionary<string, object?>()), llamada))];

